package com.mo.economy_system.target.forge1201.network;
import com.mo.economy_system.common.network.*;import com.mo.economy_system.common.transfer.CheckedFileTransferRoutingService;import java.util.function.Supplier;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkEvent;
final class Forge1201CheckedFileTransferHandlers{private Forge1201CheckedFileTransferHandlers(){}
 static void controlRequest(CheckedFileTransferControlRequestMessage m,Supplier<NetworkEvent.Context>s){var c=s.get();ServerPlayer p=c.getSender();if(p!=null&&p.getServer()!=null){var server=p.getServer();CheckedFileTransferRoutingService.control(m,p.getUUID(),server.overworld().getGameTime(),Forge1201ClientFileCheckRuntime.transfers(server).transfers(),id->server.getPlayerList().getPlayer(id),(player,msg)->{if(msg instanceof CheckedFileTransferControlResponseMessage v)Forge1201NetworkChannel.sendToPlayer((ServerPlayer)player,v);});}c.setPacketHandled(true);}
 static void chunkRequest(CheckedFileTransferChunkRequestMessage m,Supplier<NetworkEvent.Context>s){var c=s.get();ServerPlayer p=c.getSender();if(p!=null&&p.getServer()!=null){var server=p.getServer();CheckedFileTransferRoutingService.chunk(m,p.getUUID(),server.overworld().getGameTime(),Forge1201ClientFileCheckRuntime.transfers(server).transfers(),id->server.getPlayerList().getPlayer(id),(player,msg)->{if(msg instanceof CheckedFileTransferChunkResponseMessage v)Forge1201NetworkChannel.sendToPlayer((ServerPlayer)player,v);else if(msg instanceof CheckedFileTransferControlResponseMessage v)Forge1201NetworkChannel.sendToPlayer((ServerPlayer)player,v);});}c.setPacketHandled(true);}
 static void request(CheckedFileTransferRequestMessage m,Supplier<NetworkEvent.Context>s){Forge1201CheckedFileTransferClient.request(m);s.get().setPacketHandled(true);}static void controlResponse(CheckedFileTransferControlResponseMessage m,Supplier<NetworkEvent.Context>s){Forge1201CheckedFileTransferClient.control(m);s.get().setPacketHandled(true);}static void chunkResponse(CheckedFileTransferChunkResponseMessage m,Supplier<NetworkEvent.Context>s){Forge1201CheckedFileTransferClient.chunk(m);s.get().setPacketHandled(true);}}
